 HttpResponse<String> upload(ChainIntegrationTest.Session s,Path p,String submission,String upload,String filename)throws Exception{
  countUploadAttempt();
  String boundary="IAS"+UUID.randomUUID().toString().replace("-","");StringBuilder meta=new StringBuilder();for(var e:new LinkedHashMap<>(Map.of("submissionId",submission,"deviceId",h.deviceA.get("id").toString(),"expectedOwnershipVersion","1","sha256",sha(p))).entrySet())meta.append("--").append(boundary).append("\r\nContent-Disposition: form-data; name=\"").append(e.getKey()).append("\"\r\n\r\n").append(e.getValue()).append("\r\n");meta.append("--").append(boundary).append("\r\nContent-Disposition: form-data; name=\"file\"; filename=\"").append(filename).append("\"\r\nContent-Type: text/html\r\n\r\n");
  var request=HttpRequest.newBuilder(URI.create("http://127.0.0.1:8080/api/ticket/files")).timeout(Duration.ofSeconds(125)).header("Origin","http://127.0.0.1:5173").header("Cookie",s.cookie).header("X-CSRF-TOKEN",s.csrf).header("Idempotency-Key",upload).header("Content-Type","multipart/form-data; boundary="+boundary).POST(HttpRequest.BodyPublishers.concat(HttpRequest.BodyPublishers.ofString(meta.toString()),HttpRequest.BodyPublishers.ofFile(p),HttpRequest.BodyPublishers.ofString("\r\n--"+boundary+"--\r\n"))).build();return h.http.send(request,HttpResponse.BodyHandlers.ofString());
 }
 HttpResponse<byte[]> binary(ChainIntegrationTest.Session s,String url,String range,String method)throws Exception{var b=HttpRequest.newBuilder(URI.create("http://127.0.0.1:8080"+url)).timeout(Duration.ofSeconds(120)).header("Cookie",s.cookie).method(method,HttpRequest.BodyPublishers.noBody());if(range!=null)b.header("Range",range);return h.http.send(b.build(),HttpResponse.BodyHandlers.ofByteArray());}
