 @Test @Order(3) void unobservedUploadExplicitSameKeyRetryAndLateOriginalHaveOneFileId()throws Exception{
  Path file=fixture("png");
  for(boolean competing:List.of(false,true)){
   String submission=UUID.randomUUID().toString(),key=UUID.randomUUID().toString(),boundary="IAS"+UUID.randomUUID().toString().replace("-","");
   StringBuilder meta=new StringBuilder();
   for(var entry:Map.of("submissionId",submission,"deviceId",h.deviceA.get("id").toString(),"expectedOwnershipVersion","1","sha256",sha(file)).entrySet())meta.append("--").append(boundary).append("\r\nContent-Disposition: form-data; name=\"").append(entry.getKey()).append("\"\r\n\r\n").append(entry.getValue()).append("\r\n");
   meta.append("--").append(boundary).append("\r\nContent-Disposition: form-data; name=\"file\"; filename=\"late.png\"\r\nContent-Type: image/png\r\n\r\n");
   var bytes=new ByteArrayOutputStream();bytes.write(meta.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));bytes.write(Files.readAllBytes(file));bytes.write(("\r\n--"+boundary+"--\r\n").getBytes(java.nio.charset.StandardCharsets.UTF_8));
   var started=new CountDownLatch(1);var release=new CountDownLatch(1);
   var body=new ByteArrayInputStream(bytes.toByteArray()){
    boolean waited;
    void waitForRelease()throws IOException{if(!waited){waited=true;started.countDown();try{if(!release.await(30,TimeUnit.SECONDS))throw new IOException("Test upload gate timed out");}catch(InterruptedException e){Thread.currentThread().interrupt();throw new IOException("Test upload gate interrupted");}}}
    @Override public synchronized int read(byte[] b,int off,int len){try{waitForRelease();}catch(IOException e){throw new UncheckedIOException(e);}return super.read(b,off,len);}
   };
   countUploadAttempt();var request=HttpRequest.newBuilder(URI.create("http://127.0.0.1:8080/api/ticket/files")).timeout(Duration.ofSeconds(45)).header("Origin","http://127.0.0.1:5173").header("Cookie",h.customer.cookie).header("X-CSRF-TOKEN",h.customer.csrf).header("Idempotency-Key",key).header("Content-Type","multipart/form-data; boundary="+boundary).POST(HttpRequest.BodyPublishers.ofInputStream(()->body)).build();
   var original=h.http.sendAsync(request,HttpResponse.BodyHandlers.ofString());
   try{
    assertTrue(started.await(10,TimeUnit.SECONDS));
    for(int i=0;i<2;i++)h.status(404,h.send(h.customer,"GET","/api/ticket/file-uploads/"+key,null,Map.of()));
    try(var c=ticketDb(false)){assertEquals(0,h.scalar(c,"SELECT COUNT(*) FROM ticket_file WHERE upload_id=?",key));}
    HttpResponse<String> retry;
    if(competing){release.countDown();retry=upload(h.customer,file,submission,key,"late.png");}
    else{retry=upload(h.customer,file,submission,key,"late.png");h.status(201,retry);release.countDown();}
    var late=original.get(45,TimeUnit.SECONDS);
    assertTrue(Set.of(200,201,409).contains(retry.statusCode()),"Retry must replay, create or report busy");
    assertTrue(Set.of(200,201,409).contains(late.statusCode()),"Late original must replay, create or report busy");
    assertEquals(1,(retry.statusCode()==201?1:0)+(late.statusCode()==201?1:0));
    if(!competing)h.status(200,late);
    for(var response:List.of(retry,late))if(response.statusCode()==409)assertEquals("OPERATION_BUSY",h.body(response).get("code"));
    var found=h.send(h.customer,"GET","/api/ticket/file-uploads/"+key,null,Map.of());h.status(200,found);var ready=h.body(found);assertEquals("READY",ready.get("state"));String id=ready.get("fileId").toString();
    for(var response:List.of(retry,late))if(response.statusCode()!=409)assertEquals(id,h.body(response).get("fileId"));
    var replay=upload(h.customer,file,submission,key,"late.png");h.status(200,replay);assertEquals(id,h.body(replay).get("fileId"));
    try(var c=ticketDb(false)){assertEquals(1,h.scalar(c,"SELECT COUNT(*) FROM ticket_file WHERE upload_id=?",key));assertEquals(1,h.scalar(c,"SELECT COUNT(*) FROM ticket_file WHERE submission_id=?",submission));assertEquals(1,h.scalar(c,"SELECT COUNT(*) FROM ticket_audit WHERE operation_id=? AND action='FILE_READY'",submission));}
   }finally{release.countDown();if(!original.isDone())original.cancel(true);}
  }
 }
 @Test @Order(3) void actualFormatsUploadReplayAndPrivateRange()throws Exception{
  for(String kind:List.of("png","jpg","pdf")){Path p=fixture(kind);String sub=UUID.randomUUID().toString(),up=UUID.randomUUID().toString();var r=upload(h.customer,p,sub,up,"fixture."+kind);h.status(201,r);var file=h.body(r);assertEquals("READY",file.get("state"));String id=file.get("fileId").toString();h.status(200,h.send(h.customer,"GET","/api/ticket/file-uploads/"+up,null,Map.of()));var repeat=upload(h.customer,p,sub,up,"fixture."+kind);h.status(200,repeat);assertEquals(id,h.body(repeat).get("fileId"));
   var auth=h.send(h.customer,"POST","/api/ticket/files/"+id+"/download-authorizations",Map.of(),Map.of());h.status(200,auth);String url=h.body(auth).get("url").toString();var full=binary(h.customer,url,null,"GET");assertEquals(200,full.statusCode());assertEquals(sha(p),HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(full.body())));var range=binary(h.customer,url,"bytes=0-7","GET");assertEquals(206,range.statusCode());assertArrayEquals(Arrays.copyOf(Files.readAllBytes(p),8),range.body());assertEquals("bytes 0-7/"+Files.size(p),range.headers().firstValue("Content-Range").orElseThrow());assertEquals(200,binary(h.customer,url,null,"HEAD").statusCode());assertEquals(0,binary(h.customer,url,null,"HEAD").body().length);assertEquals(416,binary(h.customer,url,"bytes=0-1,3-4","GET").statusCode());assertEquals(416,binary(h.customer,url,"bytes=999999999-","GET").statusCode());assertEquals(403,binary(h.a,url,null,"GET").statusCode());assertEquals(403,binary(h.b,url,null,"GET").statusCode());
   if(kind.equals("pdf")){uploaded=id;uploadedSubmission=sub;downloadUrl=url;}
  }
 }
